/**
 * Represents an HTTP service error from a backend call.
 */
export interface ServiceError {
  /**
   * HTTP error code.
   */
  code: number;
  /**
   * The error message generated by the backend.
   */
  message: string;
  /**
   * The HTTP path of the request.
   */
  path: string;
  /**
   * Used for the type guard.
   */
  type: "error";
}

/**
 * Type guard for a network call.
 */
export const isServiceError = <T>(
  response: T | null | undefined | ServiceError,
): response is ServiceError => {
  const isError =
    (response as ServiceError | null | undefined)?.type === "error";
  if (isError) {
    const message = (response as ServiceError).message;
    // biome-ignore lint/suspicious/noConsole: Need to indicate to the user that there was an error
    console.error(typeof message === "string" ? message : response);
  }

  return isError;
};
